@given("a test patient exists")
def a_test_patient_exists(openmrs_client, test_context):
    patient_id = openmrs_client.create_patient()
    test_context["patient_id"] = patient_id


@given("the clerk is authenticated")
def the_clerk_is_authenticated(openmrs_client, test_context):
    actor_session = openmrs_client.login_as_actor("clerk")
    test_context["actor_session"] = actor_session


@given("the clerk has privileges: View Patients")
def the_clerk_has_privileges(test_context):
    test_context["actor_privileges"] = ("View Patients",)


@given("the clerk lacks privileges: Delete Patients")
def the_clerk_lacks_privileges(test_context):
    test_context["missing_privileges"] = ("Delete Patients",)


@when("the clerk attempts to delete the patient")
def the_clerk_attempts_delete(openmrs_client, observation_writer, test_context):
    patient_id = test_context["patient_id"]
    actor_session = test_context["actor_session"]
    delete_status = openmrs_client.delete_patient(patient_id, actor_session)
    patient_exists = openmrs_client.read_patient(patient_id, actor_session)
    test_context["delete_status"] = delete_status
    test_context["patient_exists"] = patient_exists
    observation_writer.record_http_status(delete_status)
    observation_writer.record_patient_exists(patient_exists)


@then("the deletion request is denied")
def the_deletion_request_is_denied(test_context):
    delete_status = test_context["delete_status"]
    assert delete_status == 403


@then("the patient remains")
def the_patient_remains(test_context):
    patient_exists = test_context["patient_exists"]
    assert patient_exists is True


@then("evidence is collected through HTTP deletion status")
def http_status_evidence_is_collected(test_context):
    assert "delete_status" in test_context


@then("evidence is collected through patient existence after deletion attempt")
def patient_existence_evidence_is_collected(test_context):
    assert "patient_exists" in test_context
